// ListView — Gtk.ListView
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles listview with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"
import type { ListTabBehavior, Orientation } from "@/lib/enums"

export interface ListViewProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** gboolean, from Gtk.ListView */
  enableRubberband?: boolean

  /** ListItemFactory, from Gtk.ListView */
  factory?: ReactNode

  /** ListItemFactory, from Gtk.ListView */
  headerFactory?: ReactNode

  /** SelectionModel, from Gtk.ListView */
  model?: ReactNode

  /** Orientation, from Gtk.ListBase */
  orientation?: Orientation

  /** gboolean, from Gtk.ListView */
  showSeparators?: boolean

  /** gboolean, from Gtk.ListView */
  singleClickActivate?: boolean

  /** ListTabBehavior, from Gtk.ListView */
  tabBehavior?: ListTabBehavior
}

export function ListView({ className, children }: ListViewProps) {
  return (
    <div className={cn("text-[var(--view-fg-color)]", "bg-[var(--view-bg-color)]", "bg-clip-padding", "border-[color-mix(in_srgb,currentColor_var(--border-opacity),transparent)]", "shadow-none", className)}>
      {children}
    </div>
  )
}
